# Surah Al-Isra (chapter 17) — part 3: ayat 21-30 (IDs 2050-2059)
SURAH = 17

ENTRIES = {
2050: (
"دیکھیے ہم نے ان میں سے بعض کو بعض پر کیسے فضیلت دی — اور یقیناً آخرت زیادہ درجات والی ہے اور زیادہ فضیلت والی ہے",
"""۱۔ دنیا کی فضیلوں کی ترتیب آخرت کی سی نہیں؛ آخرت کے درجات عظیم ہیں۔
۲۔ ’’انظُرْ كَيْفَ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍ وَلَلْآخِرَۃُ أَكْبَرُ دَرَجَاتٍ وَأَكْبَرُ تَفْضِيلًا‘‘ — دیکھیے ہم نے ان میں سے بعض کو بعض پر کیسے فضیلت دی — اور یقیناً آخرت زیادہ درجات والی ہے اور زیادہ فضیلت والی ہے — یعنی دیکھو ہم نے دنیا میں بعض کو بعض پر کیسے فضیلت دی — اور آخرت کے درجات اور فضیلتیں بہت زیادہ ہیں۔
۳۔ عملی سبق: دنیا کی کمی کا غم نہ کرو؛ آخرت میں سب سے بڑی فضیلت مؤمنوں کے لیے ہے۔"""
),
2051: (
"اللہ کے ساتھ کوئی دوسرا معبود نہ بناؤ ورنہ تم مذموم اور بے کس ہو کر بیٹھ جاؤ گے",
"""۱۔ شرک — ذلت اور بے بسی؛ توحید ہی اصل عزت ہے۔
۲۔ ’’لَا تَجْعَلْ مَعَ اللَّهِ إِلَٰهًا آخَرَ فَتَقْعُدَ مَذْمُومًا مَّخْذُولًا‘‘ — اللہ کے ساتھ کوئی دوسرا معبود نہ بناؤ ورنہ تم مذموم اور بے کس ہو کر بیٹھ جاؤ گے — یعنی اللہ کے ساتھ کوئی اور معبود نہ بناؤ ورنہ تم شرمندے اور بے کس ہو کر رہ جاؤ گے۔
۳۔ عملی سبق: شرک سے دوری توحید کی علامت ہے؛ تقویٰ اختیار کرو اور اللہ پر توکل کرو۔"""
),
2052: (
"اور آپ کے رب نے فیصلہ کیا کہ تم اس کے سوا کسی کی عبادت نہ کرو — اور والدین کے ساتھ حسن سلوک کرو — اگر ان میں سے کوئی ایک یا دونوں آپ کے سامنے بڑھاپے تک پہنچ جائیں تو ان سے اُف تک نہ کہو — اور نہ انہیں جھڑکیں — اور ان سے نرمی کے ساتھ بات کریں",
"""۱۔ والدین کا مقام عبادت کے بعد؛ بڑھاپے میں ان کا خیال رکھنا فرض؛ اُف کہنا گناہ۔
۲۔ ’’وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِندَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلَاهُمَا فَلَا تَقُل لَّهُمَا أُفٍّ وَلَا تَنْهَرْهُمَا وَقُل لَّهُمَا قَوْلًا كَرِيمًا‘‘ — اور آپ کے رب نے فیصلہ کیا کہ تم اس کے سوا کسی کی عبادت نہ کرو — اور والدین کے ساتھ حسن سلوک کرو — اگر ان میں سے کوئی ایک یا دونوں آپ کے سامنے بڑھاپے تک پہنچ جائیں تو ان سے اُف تک نہ کہو — اور نہ انہیں جھڑکیں — اور ان سے نرمی کے ساتھ بات کریں — یعنی آپ کے رب کا فیصلہ ہے کہ صرف اسی کی عبادت کرو — اور والدین کے ساتھ اچھا سلوک کرو — اگر ان میں سے کوئی یا دونوں تمہارے سامنے بڑھ جائیں تو ان سے اُف نہ کہو اور انہیں جھڑک نہ دو اور ان سے عزت بھری بات کرو۔
۳۔ عملی سبق: والدین کی خدمت اختیار ایمان ہے؛ بڑھاپے میں ان کی نگہبانی فرض ہے۔"""
),
2053: (
"اور ان کے لیے عاجزی کا بازو — رحمت کی وجہ سے — جھکا دو — اور دعا کرو کہ اے میرے رب ان دونوں پر رحم کر جیسے انہوں نے مجھے بچپن میں پالا",
"""۱۔ والدین کے سامنے نہایت عاجزی؛ ان کے لیے ہمیشہ دعائے رحمت۔
۲۔ ’’وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَۃِ وَقُل رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا‘‘ — اور ان کے لیے عاجزی کا بازو — رحمت کی وجہ سے — جھکا دو — اور دعا کرو کہ اے میرے رب ان دونوں پر رحم کر جیسے انہوں نے مجھے بچپن میں پالا — یعنی رحمت کی وجہ سے ان کے سامنے عاجزی کا بازو جھکا دو اور دعا کرو کہ اے رب میرے ان دونوں پر رحم کر جیسا کہ انہوں نے مجھے بچپن میں پالا۔
۳۔ عملی سبق: والدین کے لیے رحمت کی دعائیں کرتے رہیں؛ یہ ان کا حق ہے۔"""
),
2054: (
"آپ کا رب بہتر جانتا ہے جو تمہارے نفسوں میں ہے — اگر تم نیک ہو تو یقیناً وہ باز آنے والوں کے لیے بخشنے والا ہے",
"""۱۔ اللہ دل کی نیت جانتا ہے؛ نیک اور توبہ کرنے والوں کو بخشش ملتی ہے۔
۲۔ ’’رَّبُّكُمْ أَعْلَمُ بِمَا فِي نُفُوسِكُمْ إِن تَكُونُوا صَالِحِينَ فَإِنَّهُ كَانَ لِلْأَوَّابِينَ غَفُورًا‘‘ — آپ کا رب بہتر جانتا ہے جو تمہارے نفسوں میں ہے — اگر تم نیک ہو تو یقیناً وہ باز آنے والوں کے لیے بخشنے والا ہے — یعنی تمہارا رب تمہارے نفسوں میں جو ہے وہ جانتا ہے — اگر تم نیک ہو تو وہ باز آنے والوں کو بخشنے والا ہے۔
۳۔ عملی سبق: نیت درست رکھو؛ توبہ کرنے والوں کے لیے اللہ کا دروازہ کھلا ہے۔"""
),
2055: (
"اور رشتے داروں کو ان کا حق دو — اور مسکینوں اور مسافر کو بھی — اور فضول خرچی نہ کرو",
"""۱۔ قرابت کی ادائیگی؛ مسکینوں کی مدد؛ مسافروں کا خیال؛ فضول خرچی سے پرہیز۔
۲۔ ’’وَآتِ ذَا الْقُرْبَىٰ حَقَّهُ وَالْمِسْكِينَ وَابْنَ السَّبِيلِ وَلَا تُبَذِّرْ تَبْذِيرًا‘‘ — اور رشتے داروں کو ان کا حق دو — اور مسکینوں اور مسافر کو بھی — اور فضول خرچی نہ کرو — یعنی رشتے داروں کو ان کا حق دے دو اور مسکینوں اور مسافر کو بھی — اور فضول خرچی نہ کرو۔
۳۔ عملی سبق: رشتے داروں اور غریبوں کی مدد کرو؛ مال کو فضول خرچ نہ کرو۔"""
),
2056: (
"بے شک فضول خرچ کرنے والے شیطان کے بھائی ہیں — اور شیطان اپنے رب کا ناشکرا ہے",
"""۱۔ فضول خرچی شیطانی ہے؛ شیطان ہی ناشکرا ہے؛ اسراف سے بچو۔
۲۔ ’’إِنَّ الْمُبَذِّرِينَ كَانُوا إِخْوَانَ الشَّيَاطِينِ وَكَانَ الشَّيْطَانُ لِرَبِّهِ كَفُورًا‘‘ — بے شک فضول خرچ کرنے والے شیطان کے بھائی ہیں — اور شیطان اپنے رب کا ناشکرا ہے — یعنی بے شک فضول خرچ کرنے والے شیطانوں کے بھائی ہیں — اور شیطان اپنے رب کا بہت ناشکرا ہے۔
۳۔ عملی سبق: مال کا صرف اپنی اور اپنے اہل و عیال کے لیے ہو؛ بخل بھی نہ کرو اور فضول بھی نہ کرو۔"""
),
2057: (
"اور اگر تم ان سے بالکل منہ موڑ رہے ہو — اپنے رب کی رحمت کی امید میں جس کی تمہیں امید ہے — تو ان سے نرمی کے ساتھ بات کرو",
"""۱۔ اقتصادی تنگی میں بھی نرمی سے بات کرو؛ فضیلت یہ ہے کہ جس کے پاس کچھ نہ ہو وہ بھی اچھی بات کہے۔
۲۔ ’’وَإِمَّا تُعْرِضَنَّ عَنْهُمُ ابْتِغَاءَ رَحْمَۃٍ مِّن رَّبِّكَ تَرْجُوهَا فَقُل لَّهُمْ قَوْلًا مَّيْسُورًا‘‘ — اور اگر تم ان سے بالکل منہ موڑ رہے ہو — اپنے رب کی رحمت کی امید میں جس کی تمہیں امید ہے — تو ان سے نرمی کے ساتھ بات کرو — یعنی اگر تم ان سے بالکل نہ دو تو کم از کم نرمی سے بات کرو — اپنے رب کی رحمت کی امید میں جس کی تمہیں امید ہے۔
۳۔ عملی سبق: مدد نہ کر سکو تو بھی اچھے الفاظ بولو؛ حسنِ اخلاق ہی صدقہ ہے۔"""
),
2058: (
"اور اپنا ہاتھ اپنی گردن سے بندھ کے نہ رکھو — اور نہ اسے بالکل پورا پھیلا دو — ورنہ تم ملامت زدہ اور کم ساری والے ہو کر بیٹھ جاؤ گے",
"""۱۔ بخیلی اور فضول خرچی دونوں مذموم؛ توازن اخلاق ایمانی کا حصہ ہے۔
۲۔ ’’وَلَا تَجْعَلْ يَدَكَ مَغْلُولَۃً إِلَىٰ عُنُقِكَ وَلَا تَبْسُطْهَا كُلَّ الْبَسْطِ فَتَقْعُدَ مَلُومًا مَّحْسُورًا‘‘ — اور اپنا ہاتھ اپنی گردن سے بندھ کے نہ رکھو — اور نہ اسے بالکل پورا پھیلا دو — ورنہ تم ملامت زدہ اور کم ساری والے ہو کر بیٹھ جاؤ گے — یعنی اپنا ہاتھ بندہ کر کے نہ رکھو اور نہ بالکل کھول دو ورنہ تم شرمندہ اور خالی ہاتھ بیٹھ جاؤ گے۔
۳۔ عملی سبق: مال میں توازن رکھو؛ بخل بھی نہ کرو؛ اسراف بھی نہ کرو۔"""
),
2059: (
"بے شک آپ کا رب جس کے لیے چاہتا ہے رزق کشادہ کرتا ہے اور جس کے لیے چاہتا ہے تنگ کرتا ہے — بے شک وہ اپنے بندوں کے بارے میں خوب خبر رکھنے والا دیکھنے والا ہے",
"""۱۔ رزق کی تقسیم اللہ کے ہاتھ میں ہے؛ اللہ سب جانتا ہے کہ کس کو کتنا دینا چاہیے۔
۲۔ ’’إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ كَانَ بِعِبَادِهِ خَبِيرًا بَصِيرًا‘‘ — بے شک آپ کا رب جس کے لیے چاہتا ہے رزق کشادہ کرتا ہے اور جس کے لیے چاہتا ہے تنگ کرتا ہے — بے شک وہ اپنے بندوں کے بارے میں خوب خبر رکھنے والا دیکھنے والا ہے — یعنی آپ کا رب جس کے لیے چاہتا ہے رزق کشادہ کرتا ہے اور جسے چاہتا ہے کم دیتا ہے — بے شک وہ اپنے بندوں کا پورا جاننے والا اور دیکھنے والا ہے۔
۳۔ عملی سبق: رزق کی کمی پر کفر نہ کرو؛ اللہ کی عطا پر صبر کرو اور شکر کرو۔"""
),
}
